-- Club Yatri destinations import (generated by database/tools/import_destinations.py)
-- Safe to re-run. Applied automatically on deploy by deploy-migrate.php.
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `destinations` (
  `id` INT UNSIGNED NOT NULL PRIMARY KEY,
  `slug` VARCHAR(160) NOT NULL UNIQUE,
  `name` VARCHAR(160) NOT NULL,
  `region` VARCHAR(80) DEFAULT NULL,
  `country` VARCHAR(80) NOT NULL,
  `location_type` ENUM('DOMESTIC', 'INTERNATIONAL') NOT NULL,
  `tagline` VARCHAR(255) DEFAULT NULL,
  `description` TEXT DEFAULT NULL,
  `highlights` TEXT DEFAULT NULL,
  `best_time` VARCHAR(255) DEFAULT NULL,
  `meta_title` VARCHAR(255) DEFAULT NULL,
  `meta_description` VARCHAR(500) DEFAULT NULL,
  `hero_image` VARCHAR(255) DEFAULT NULL,
  `source_url` VARCHAR(500) DEFAULT NULL,
  `featured` TINYINT(1) NOT NULL DEFAULT 0,
  `is_published` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  KEY `idx_destinations_type` (`location_type`, `is_published`),
  KEY `idx_destinations_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE slug=VALUES(slug), name=VALUES(name), region=VALUES(region), country=VALUES(country), location_type=VALUES(location_type), tagline=VALUES(tagline), description=VALUES(description), highlights=VALUES(highlights), best_time=VALUES(best_time), meta_title=VALUES(meta_title), meta_description=VALUES(meta_description), hero_image=VALUES(hero_image), source_url=VALUES(source_url), featured=VALUES(featured), is_published=VALUES(is_published);

