INSERT INTO `destinations` (id, slug, name, region, country, location_type, tagline, description, highlights, best_time, meta_title, meta_description, hero_image, source_url, featured, is_published) VALUES
(1, 'agra', 'Agra', 'India', 'India', 'DOMESTIC', NULL, 'Agra is a city on the banks of the Yamuna river in the Indian state of Uttar Pradesh, famous for its Mughal-era buildings.', 'Taj Mahal; Agra Fort; Fatehpur Sikri', NULL, NULL, NULL, 'assets/images/places/agra.webp', 'https://commons.wikimedia.org/wiki/File:Taj_Mahal,_Agra,_India_edit2.jpg', 0, 1),
(2, 'ahmedabad', 'Ahmedabad', 'India', 'India', 'DOMESTIC', NULL, 'Ahmedabad, the largest city in Gujarat, is known for its historical sites and as the former home of Mahatma Gandhi.', 'Sabarmati Ashram; Adalaj Stepwell; Kankaria Lake', NULL, NULL, NULL, 'assets/images/places/ahmedabad.webp', 'https://commons.wikimedia.org/wiki/File:Sabarmati_Ashram_-_Ahmedabad_-_Gujarat_-_DSC001.jpg', 0, 1),
(3, 'ajmer', 'Ajmer', 'India', 'India', 'DOMESTIC', NULL, 'Ajmer is a city in Rajasthan, known for the shrine of the Sufi saint Garib Nawaz.', 'Ajmer Sharif Dargah; Ana Sagar Lake; Adhai Din Ka Jhonpra', NULL, NULL, NULL, 'assets/images/places/ajmer.webp', 'https://commons.wikimedia.org/wiki/File:Ajmer_Sharif,_Dargah_of_Mainuddin_Chisti_in_Ajmer,_Rajasthan_27.jpg', 0, 1),
(4, 'alleppey', 'Alleppey', 'India', 'India', 'DOMESTIC', NULL, 'Alappuzha (or Alleppey) is a city on the Laccadive Sea in the southern Indian state of Kerala. It\'s best known for houseboat cruises along the rustic Kerala backwaters, a network of tranquil canals and lagoons.', 'Alappuzha Beach; Vembanad Lake; Marari Beach', NULL, NULL, NULL, 'assets/images/places/alleppey.webp', 'https://commons.wikimedia.org/wiki/File:Alleppey_beach.jpg', 0, 1),
(5, 'amritsar', 'Amritsar', 'India', 'India', 'DOMESTIC', NULL, 'Amritsar is a city in the northwestern Indian state of Punjab, 28 kilometers from the border with Pakistan. At the center of its walled old town, the gilded Golden Temple (Harmandir Sahib) is the holiest gurdwara (religious complex) of the Sikh religion.', 'Golden Temple; Jallianwala Bagh; Wagah Border', NULL, NULL, NULL, 'assets/images/places/amritsar.webp', 'https://commons.wikimedia.org/wiki/File:Hamandir_Sahib_(Golden_Temple).jpg', 0, 1),
(6, 'auli', 'Auli', 'India', 'India', 'DOMESTIC', NULL, 'Auli is a Himalayan ski resort and hill station in the north Indian state of Uttarakhand. It is surrounded by coniferous and oak forests, plus the Nanda Devi and Nar Parvat mountains.', 'Auli Artificial Lake; Gorson Bugyal; Chattrakund', NULL, NULL, NULL, 'assets/images/places/auli.webp', 'https://commons.wikimedia.org/wiki/File:Auli_Ski_Resort_in_summer_2012.jpg', 0, 1),
(7, 'aurangabad', 'Aurangabad', 'India', 'India', 'DOMESTIC', NULL, 'Aurangabad is a city in Maharashtra state, in India. It is known for the 17th-century marble Bibi ka Maqbara shrine, styled on the Taj Mahal.', 'Ajanta Caves; Ellora Caves; Bibi Ka Maqbara', NULL, NULL, NULL, 'assets/images/places/aurangabad.webp', 'https://commons.wikimedia.org/wiki/File:Aurangabad_-_Ajanta_Caves_(57).JPG', 0, 1),
(8, 'ayodhya', 'Ayodhya', 'India', 'India', 'DOMESTIC', NULL, 'Ayodhya, a city on the banks of the Sarayu river in the Indian state of Uttar Pradesh, is the birthplace of Rama and setting of the great epic Ramayana.', 'Ram Janmabhoomi; Hanuman Garhi; Kanak Bhawan', NULL, NULL, NULL, 'assets/images/places/ayodhya.webp', 'https://commons.wikimedia.org/wiki/File:Hanuman_Garhi_Temple-20.jpg', 0, 1),
(9, 'bali', 'Bali', 'Indonesia', 'Indonesia', 'INTERNATIONAL', NULL, 'Bali is an Indonesian island known for its forested volcanic mountains, iconic rice paddies, beaches and coral reefs.', 'Ubud; Kuta; Tanah Lot Temple', NULL, NULL, NULL, 'assets/images/places/bali.webp', 'https://commons.wikimedia.org/wiki/File:Fields_in_Ubud,_Bali,_Indonesia,_20220823_0956_0313.jpg', 0, 1),
(10, 'banaras', 'Banaras', 'India', 'India', 'DOMESTIC', NULL, 'Explore handpicked partner properties in Banaras.', 'evening Arti', NULL, NULL, NULL, 'assets/images/places/banaras.webp', 'https://commons.wikimedia.org/wiki/File:BHU_Main_Gate,_Banaras_Hindu_University.jpg', 0, 1),
(11, 'bandipur', 'Bandipur', 'India', 'India', 'DOMESTIC', NULL, 'Bandipur National Park, an 874-sq.-km forested reserve in the southern Indian state of Karnataka, is known for its small population of tigers.', 'Bandipur National Park; Gopalaswamy Betta; Bandipur Tiger Reserve', NULL, NULL, NULL, 'assets/images/places/bandipur.webp', 'https://commons.wikimedia.org/wiki/File:Elephas_maximus_(Bandipur).jpg', 0, 1),
(12, 'bangalore', 'Bangalore', 'India', 'India', 'DOMESTIC', NULL, 'Bengaluru (also called Bangalore) is the capital of India\'s southern Karnataka state. The center of India\'s high-tech industry, the city is also known for its parks and nightlife.', 'Bangalore Palace; Lalbagh Botanical Garden; Cubbon Park', NULL, NULL, NULL, 'assets/images/places/bangalore.webp', 'https://commons.wikimedia.org/wiki/File:Gate_3_(East),_Vidhana_Soudha_(01).jpg', 0, 1),
(13, 'bangkok', 'Bangkok', 'Thailand', 'Thailand', 'INTERNATIONAL', NULL, 'Bangkok, Thailand\'s capital, is a large city known for ornate shrines and vibrant street life.', 'Grand Palace; Wat Arun; Wat Pho', NULL, NULL, NULL, 'assets/images/places/bangkok.webp', 'https://commons.wikimedia.org/wiki/File:A_roof_of_a_building_at_the_Grand_Palace,_Bangkok,_sunrise,_2017.jpg', 0, 1),
(14, 'bhimtal', 'Bhimtal', 'India', 'India', 'DOMESTIC', NULL, 'Bhimtal is a town and nagar panchayat in Nainital district in the state of Uttarakhand, India, situated at an altitude of 1370 meters above sea level and is about 22 kilometers from Nainital.', 'Bhimtal Lake; Bhimeshwar Mahadev Temple; Victoria Dam', NULL, NULL, NULL, 'assets/images/places/bhimtal.webp', 'https://commons.wikimedia.org/wiki/File:Panoramic_view_of_Bhimtal_lake_from_Aquarium_Island_Cafe_by_The_Lake_Hill.jpg', 0, 1),
(15, 'bhopal', 'Bhopal', 'India', 'India', 'DOMESTIC', NULL, 'Bhopal is a city in the central Indian state of Madhya Pradesh. It\'s one of India\'s greenest cities. There are two main lakes, the Upper Lake and the Lower Lake.', 'Van Vihar National Park; Upper Lake; Taj-ul-Masajid', NULL, NULL, NULL, 'assets/images/places/bhopal.webp', 'https://commons.wikimedia.org/wiki/File:Upper_Lake,_Bhopal,_M.P.jpg', 0, 1),
(16, 'bhuj', 'Bhuj', 'India', 'India', 'DOMESTIC', NULL, 'Bhuj is a city in the state of Gujarat, western India. It is known for its centuries-old buildings, including the Aina Mahal palace, decorated with mirrors and glass.', 'Aina Mahal; Prag Mahal; Kutch Museum', NULL, NULL, NULL, 'assets/images/places/bhuj.webp', 'https://commons.wikimedia.org/wiki/File:Aina_mahal.jpg_01.jpg', 0, 1),
(17, 'bhutan', 'Bhutan', 'Bhutan', 'Bhutan', 'INTERNATIONAL', NULL, 'Bhutan, a Buddhist kingdom on the Himalayas\' eastern edge, is known for its monasteries, fortresses (or dzongs) and dramatic landscapes.', 'Paro Taktsang (Tiger\'s Nest); Punakha Dzong; Thimphu', NULL, NULL, NULL, 'assets/images/places/bhutan.webp', 'https://commons.wikimedia.org/wiki/File:Paro_Taktsang,_Bhutan_(edited).jpg', 0, 1),
(18, 'bikaner', 'Bikaner', 'India', 'India', 'DOMESTIC', NULL, 'Bikaner is a city in the northwest of the state of Rajasthan, India. It is located 330 kilometres northwest of the state capital, Jaipur.', 'Junagarh Fort; Karni Mata Temple; Lalgarh Palace', NULL, NULL, NULL, 'assets/images/places/bikaner.webp', 'https://commons.wikimedia.org/wiki/File:20191211_Junagarh_Fort,_Bikaner,_India_1547_8077_DxO.jpg', 0, 1),
(19, 'canary-islands', 'Canary Islands', 'Spain', 'Spain', 'INTERNATIONAL', NULL, 'The Canary Islands, a Spanish archipelago off the coast of northwestern Africa, are rugged volcanic isles known for their black- and white-sand beaches.', 'Teide National Park; Tenerife; Gran Canaria', NULL, NULL, NULL, 'assets/images/places/canary-islands.webp', 'https://commons.wikimedia.org/wiki/File:Caldera_Las_Ca%C3%B1adas_mit_Roques_de_Garc%C3%ADa_und_TF-21.jpg', 0, 1),
(20, 'chandigarh', 'Chandigarh', 'India', 'India', 'DOMESTIC', NULL, 'Chandigarh, the capital of the northern Indian states of Punjab and Haryana, was designed by the modernist architect Le Corbusier.', 'Rock Garden; Sukhna Lake; Zakir Hussain Rose Garden', NULL, NULL, NULL, 'assets/images/places/chandigarh.webp', 'https://commons.wikimedia.org/wiki/File:Chandigarh_Rock_Garden_4.jpg', 0, 1),
(21, 'chennai', 'Chennai', 'India', 'India', 'DOMESTIC', NULL, 'Chennai, on the Bay of Bengal in eastern India, is the capital of the state of Tamil Nadu. The city is home to Fort St. George, built in 1644 and now a museum.', 'Marina Beach; Kapaleeshwarar Temple; Fort St. George', NULL, NULL, NULL, 'assets/images/places/chennai.webp', 'https://commons.wikimedia.org/wiki/File:MGR_Memorial,_Marina_Beach.jpg', 0, 1),
(22, 'cochin', 'Cochin', 'India', 'India', 'DOMESTIC', NULL, 'Kochi (also known as Cochin) is a major port city on the south-west coast of India by the Arabian Sea.', 'Fort Kochi; Mattancherry Palace; Chinese Fishing Nets', NULL, NULL, NULL, 'assets/images/places/cochin.webp', 'https://commons.wikimedia.org/wiki/File:Cochin_Club_in_Fort_Kochi_03.jpg', 0, 1),
(23, 'coimbatore', 'Coimbatore', 'India', 'India', 'DOMESTIC', NULL, 'Coimbatore is a city in the south Indian state of Tamil Nadu. To the northwest is the centuries-old, Dravidian-style Arulmigu Subramaniyaswami Temple, Marudamalai.', 'Marudhamalai Hill Temple; Dhyanalinga; Siruvani Waterfalls', NULL, NULL, NULL, 'assets/images/places/coimbatore.webp', 'https://commons.wikimedia.org/wiki/File:Marudhamalai!_Coimbatore_(48971821873).jpg', 0, 1),
(24, 'coorg', 'Coorg', 'India', 'India', 'DOMESTIC', NULL, 'Kodagu, also known as Coorg, is a rural district in the southwest Indian state of Karnataka. In the area\'s north, the Madikeri Fort has 2 life-size elephant statues at its entrance, plus a Gothic-style church with a museum.', 'Abbey Falls; Raja\'s Seat; Dubare Elephant Camp', NULL, NULL, NULL, 'assets/images/places/coorg.webp', 'https://commons.wikimedia.org/wiki/File:ABBEY_FALLS_,COORG_,KARNATAKA.jpg', 0, 1),
(25, 'dalhousie', 'Dalhousie', 'India', 'India', 'DOMESTIC', NULL, 'Dalhousie is a high-altitude town spread across 5 hills near the Dhauladhar mountain range in the north Indian state of Himachal Pradesh.', 'Khajjiar Lake; Panchpula; Kalatop Wildlife Sanctuary', NULL, NULL, NULL, 'assets/images/places/dalhousie.webp', 'https://commons.wikimedia.org/wiki/File:Khajjiar_Dalhousie.jpg', 0, 1),
(26, 'dehradun', 'Dehradun', 'India', 'India', 'DOMESTIC', NULL, 'Dehradun is the capital of the Indian state of Uttarakhand, near the Himalayan foothills. At its core is the 6-sided Ghanta Ghar clock tower.', 'Robber\'s Cave; Sahastradhara; Mindrolling Monastery', NULL, NULL, NULL, 'assets/images/places/dehradun.webp', 'https://commons.wikimedia.org/wiki/File:Section_of_Robber_Cave_Dehradun_Uttarakhand_India.jpg', 0, 1),
(27, 'dhanaulti', 'Dhanaulti', 'India', 'India', 'DOMESTIC', NULL, 'Dhanaulti is a quiet hill station at an elevation of 2286 meters above sea level, it offers panoramic views of the lofty Himalayas.', 'Eco Park; Surkanda Devi Temple; Potato Farm', NULL, NULL, NULL, 'assets/images/places/dhanaulti.webp', 'https://commons.wikimedia.org/wiki/File:Dhanaulti_Eco_park.JPG', 0, 1),
(28, 'dharamshala', 'Dharamshala', 'India', 'India', 'DOMESTIC', NULL, 'Dharamshala is a city in the Indian state of Himachal Pradesh. Surrounded by cedar forests on the edge of the Himalayas, this hillside city is home to the Dalai Lama and the Tibetan government-in-exile.', 'HPCA Stadium; Tsuglagkhang Complex; Dalai Lama Temple', NULL, NULL, NULL, 'assets/images/places/dharamshala.webp', 'https://commons.wikimedia.org/wiki/File:Dhauladhar_alpenglow_above_Dharamshala,_India.jpg', 0, 1),
(29, 'dubai', 'Dubai', 'United Arab Emirates', 'United Arab Emirates', 'INTERNATIONAL', NULL, 'Dubai is a city and emirate in the United Arab Emirates known for luxury shopping, ultramodern architecture and a lively nightlife scene.', 'Burj Khalifa; The Dubai Mall; The Dubai Fountain', NULL, NULL, NULL, 'assets/images/places/dubai.webp', 'https://commons.wikimedia.org/wiki/File:The_making_of_Burj_Khalifa,_Dubai_(Ank_Kumar)_09.jpg', 0, 1),
(30, 'gangtok', 'Gangtok', 'India', 'India', 'DOMESTIC', NULL, 'Gangtok is the capital of the mountainous northern Indian state of Sikkim. Established as a Buddhist pilgrimage site in the 1840s, the city became capital of an independent monarchy after British rule ended.', 'Nathula Pass; MG Marg; Rumtek Monastery', NULL, NULL, NULL, 'assets/images/places/gangtok.webp', 'https://commons.wikimedia.org/wiki/File:Gangtok_09.jpg', 0, 1),
(31, 'gaya', 'Gaya', 'India', 'India', 'DOMESTIC', NULL, 'Gaya is a holy city beside the Falgu River, in the northeast Indian state of Bihar. It is a site of pilgrimage for Hindus and Buddhists.', 'Mahabodhi Temple; Bodhi Tree; Great Buddha Statue', NULL, NULL, NULL, 'assets/images/places/gaya.webp', 'https://commons.wikimedia.org/wiki/File:Votive_Stupas_-_Mahabodhi_Temple_Complex_-_Bodh_Gaya_(13).jpg', 0, 1),
