(35, 'gwalior', 'Gwalior', 'India', 'India', 'DOMESTIC', NULL, 'Gwalior is a city in the central Indian state of Madhya Pradesh. It is known for its palaces and temples, including the Sas Bahu Ka Mandir intricately carved Hindu temple.', 'Gwalior Fort; Jai Vilas Palace; Sas Bahu Temple', NULL, NULL, NULL, 'assets/images/places/gwalior.webp', 'https://commons.wikimedia.org/wiki/File:Gwalior_fort_view_003_(15).jpg', 0, 1),
(36, 'haridwar', 'Haridwar', 'India', 'India', 'DOMESTIC', NULL, 'Haridwar is an ancient city and important Hindu pilgrimage site in North India\'s Uttarakhand state, where the River Ganges exits the Himalayan foothills.', 'Har Ki Pauri; Mansa Devi Temple; Chandi Devi Temple', NULL, NULL, NULL, 'assets/images/places/haridwar.webp', 'https://commons.wikimedia.org/wiki/File:Aarti_at_Har_ki_Pauri_on_Explore.jpg', 0, 1),
(37, 'hyderabad', 'Hyderabad', 'India', 'India', 'DOMESTIC', NULL, 'Hyderabad is the capital of southern India\'s Telangana state. A major center for the technology industry, it\'s home to many upscale restaurants and shops.', 'Charminar; Golkonda Fort; Hussain Sagar Lake', NULL, NULL, NULL, 'assets/images/places/hyderabad.webp', 'https://commons.wikimedia.org/wiki/File:Minaret_of_charminar_12032012.jpg', 0, 1),
(38, 'indonesia', 'Indonesia', 'Indonesia', 'Indonesia', 'INTERNATIONAL', NULL, 'Indonesia, a Southeast Asian nation made up of thousands of volcanic islands, is home to hundreds of ethnic groups speaking many different languages.', 'Bali; Borobudur Temple; Komodo National Park', NULL, NULL, NULL, 'assets/images/places/indonesia.webp', 'https://commons.wikimedia.org/wiki/File:Sunset,_Kuta,_Bali,_Indonesia,_20220825_1755_0879.jpg', 0, 1),
