(45, 'jodhpur', 'Jodhpur', 'India', 'India', 'DOMESTIC', NULL, 'Jodhpur is a city in the Thar Desert of the northwest Indian state of Rajasthan. Its 15th-century Mehrangarh Fort is a former palace that\'s now a museum.', 'Mehrangarh Fort; Umaid Bhawan Palace; Jaswant Thada', NULL, NULL, NULL, 'assets/images/places/jodhpur.webp', 'https://commons.wikimedia.org/wiki/File:20191210_Mehrangarh_Fort,_Jodhpur_1016_7834.jpg', 0, 1),
(46, 'kandaghat', 'Kandaghat', 'India', 'India', 'DOMESTIC', NULL, 'Kandaghat is a small town and tehsil in the Solan district of Himachal Pradesh, India. It is on the Kalka-Shimla National Highway No. 22.', 'Chail Palace; Sadhupul Lake; Mohan Park', NULL, NULL, NULL, 'assets/images/places/kandaghat.webp', 'https://commons.wikimedia.org/wiki/File:Kandaghat,_Himachal_Pradesh_%E0%A4%95%E0%A4%82%E0%A4%A1%E0%A4%BE%E0%A4%98%E0%A4%BE%E0%A4%9F,_%E0%A4%B9%E0%A4%BF%E0%A4%AE%E0%A4%BE%E0%A4%9A%E0%A4%B2_%E0%A4%AA%E0%A5%8D%E0%A4%B0%E0%A4%A6%E0%A5%87%E0%A4%B6.jpeg', 0, 1),
(47, 'kanha-national-park', 'Kanha National Park', 'India', 'India', 'DOMESTIC', NULL, 'Kanha National Park, also known as Kanha Tiger Reserve, is a vast expanse of grassland and forest in the central Indian state of Madhya Pradesh.', 'Kanha Tiger Reserve; Kanha Museum; Bamni Dadar', NULL, NULL, NULL, 'assets/images/places/kanha-national-park.webp', 'https://commons.wikimedia.org/wiki/File:Southern_plains_grey_langur_(Semnopithecus_dussumieri)_female_head.jpg', 0, 1),
(48, 'kasauli', 'Kasauli', 'India', 'India', 'DOMESTIC', NULL, 'Kasauli is a small hill town in the north Indian state of Himachal Pradesh. It is home to gabled colonial-era houses, orchards and green-roofed Christ Church, dating from the mid-19th century.', 'Monkey Point; Mall Road; Sunset Point', NULL, NULL, NULL, 'assets/images/places/kasauli.webp', 'https://commons.wikimedia.org/wiki/File:SUNSET_AT_KASAULI_1.jpg', 0, 1),
(49, 'katra', 'Katra', 'India', 'India', 'DOMESTIC', NULL, 'Katra or Katra Vaishno Devi, as it is popularly known, is a small town in Reasi district in the union territory of Jammu and Kashmir, India, situated in the foothills of the Trikuta Mountains, where the holy shrine of Vaishno Devi is located.', 'Vaishno Devi Temple; Bhairavnath Temple; Sanjichhat', NULL, NULL, NULL, 'assets/images/places/katra.webp', 'https://commons.wikimedia.org/wiki/File:Katra_Vaishno_Devi_temple_Seen1.jpg', 0, 1),
(50, 'kausani', 'Kausani', 'India', 'India', 'DOMESTIC', NULL, 'Kausani is a hill station and Village situated in Bageshwar district in the state of Uttarakhand, India. It is famous for its scenic splendor and its spectacular 300 km-wide panoramic view of Himalayan peaks like Trisul, Nanda Devi and Panchchuli.', 'Anasakti Ashram; Rudradhari Falls and Caves; Baijnath Temple', NULL, NULL, NULL, 'assets/images/places/kausani.webp', 'https://commons.wikimedia.org/wiki/File:Anashakti_Ashram_of_Kausani.jpg', 0, 1),
(51, 'kerala', 'Kerala', 'India', 'India', 'DOMESTIC', NULL, 'Kerala, on the Malabar Coast, is famous for its palm-lined beaches, backwaters, and spice plantations.', 'Alleppey Backwaters; Munnar Tea Gardens; Kovalam Beach', NULL, NULL, NULL, 'assets/images/places/kerala.webp', 'https://commons.wikimedia.org/wiki/File:Sun_rise_view_Alleppey_backwaters_,_Kerala_03.jpg', 0, 1),
(52, 'khandala', 'Khandala', 'India', 'India', 'DOMESTIC', NULL, 'Khandala is a hill station in the Western Ghats in the state of Maharashtra, India, about 3 kilometres from Lonavala and 7 kilometres from Karjat.', 'Duke\'s Nose; Rajmachi Fort; Amrutanjan Point', NULL, NULL, NULL, 'assets/images/places/khandala.webp', 'https://commons.wikimedia.org/wiki/File:Khandala-4.JPG', 0, 1),
(53, 'kochi', 'Kochi', 'India', 'India', 'DOMESTIC', NULL, 'Kochi (also known as Cochin) is a major port city on the south-west coast of India by the Arabian Sea. It has been a port since 1341, when a flood carved out its harbor and opened it to Arab, Chinese and European merchants.', 'Fort Kochi; Mattancherry Palace; Chinese Fishing Nets', NULL, NULL, NULL, 'assets/images/places/kochi.webp', 'https://commons.wikimedia.org/wiki/File:Kochi_chinese_fishing-net-20080215-01a.jpg', 0, 1),
